import sys
from collections import deque
MOD = 10**9 + 7

def main():
    sys.setrecursionlimit(1 << 25)
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    adj = [[] for _ in range(n+1)]
    for _ in range(n-1):
        x, y = map(int, sys.stdin.readline().split())
        adj[x].append(y)
        adj[y].append(x)

    parent = [0]*(n+1)
    depth = [0]*(n+1)
    q = deque([1])
    parent[1] = 0
    while q:
        u = q.popleft()
        for v in adj[u]:
            if parent[v] == 0 and v != parent[u]:
                parent[v] = u
                depth[v] = depth[u] + 1
                q.append(v)

    phi = [0]*(n+1)
    for i in range(1, n+1):
        phi[i] = i
    for i in range(2, n+1):
        if phi[i] == i:
            for j in range(i, n+1, i):
                phi[j] -= phi[j] // i

    res = 0
    for u in range(1, n+1):
        for v in range(1, n+1):
            if u == v:
                continue
            d = depth[u] + depth[v] - 2 * depth[parent[v]] if parent[v] != u else depth[u] + depth[v] - 2 * depth[parent[u]]
            if parent[v] == u:
                d = depth[v] - depth[u]
            elif parent[u] == v:
                d = depth[u] - depth[v]
            else:
                lca = u
                while lca != v:
                    if depth[lca] > depth[v]:
                        lca = parent[lca]
                    else:
                        v = parent[v]
